  const atr = atrLast(rows, 14);
  const price = closes[closes.length - 1];
  const atrPct = atr && price ? atr / price * 100 : 0;
  const trs = trueRanges(rows).slice(-100);
  const base = rows.slice(rows.length - trs.length);
